_tone(f0,f1,dur,type,vol,delay=0,send=0){const c=this.ctx,t=c.currentTime+delay;const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(1,f1),t+dur);g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+Math.min(0.012,dur/3));g.gain.exponentialRampToValueAtTime(0.0001,t+dur);o.connect(g);g.connect(this.sfx);if(send){const s=c.createGain();s.gain.value=send;g.connect(s);s.connect(this.reverb);}o.start(t);o.stop(t+dur+0.05);}
