_bossAlarm(){const c=this.ctx,t=c.currentTime;const o=c.createOscillator(),g=c.createGain(),f=c.createBiquadFilter();o.type='sawtooth';o.frequency.setValueAtTime(45,t);o.frequency.exponentialRampToValueAtTime(120,t+2.8);f.type='lowpass';f.frequency.setValueAtTime(200,t);f.frequency.exponentialRampToValueAtTime(1400,t+2.8);g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.28,t+2.2);g.gain.exponentialRampToValueAtTime(0.0001,t+3.2);const lfo=c.createOscillator(),lg=c.createGain();lfo.frequency.value=5;lg.gain.value=0.05;lfo.connect(lg);lg.connect(g.gain);o.connect(f);f.connect(g);g.connect(this.sfx);o.start(t);o.stop(t+3.3);lfo.start(t);lfo.stop(t+3.3);for(let i=0;i<4;i++)this._tone(600,600,0.18,'square',0.06,0.4+i*0.7,0.2);this._noise(3,'lowpass',200,900,0.14,0,0.3);}
startMusic(pattern){this._lastPattern=pattern;if(this.musicVolume<=0){this.stopMusic();return;}if(!this.ctx)return;if(this.musicPattern===pattern)return;this.musicPattern=pattern;this._musicStep=0;this._musicNext=this.ctx.currentTime+0.1;if(!this._musicTimer)this._musicTimer=setInterval(()=>this._scheduleMusic(),100);}
