_scheduleMusic(){if(!this.ctx||!this.musicPattern)return;if(this.ctx.state!=='running'){this._musicNext=this.ctx.currentTime+0.1;return;}const horizon=this.ctx.currentTime+0.3;let safety=0;while(this._musicNext<horizon&&safety++<64){if(this.musicPattern==='menu')this._musicNext+=this._stepMenu(this._musicNext);else this._musicNext+=this._stepGame(this._musicNext);}}
