const chords=[{pad:[110.00,164.81,220.00,261.63],arp:[440.00,523.25,659.25,880.00]},{pad:[87.31,130.81,174.61,220.00],arp:[349.23,440.00,523.25,698.46]},{pad:[130.81,196.00,261.63,329.63],arp:[523.25,659.25,783.99,523.25]},{pad:[98.00,146.83,196.00,246.94],arp:[392.00,493.88,587.33,783.99]}];
